def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    color = max((v for v in counts if v != bg), key=lambda v: counts[v])

    # Find the shortest non-background run that starts after the left edge
    # and has background cells following it; mark that continuation.
    choices = []
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == color]
        if cols and min(cols) > 0 and max(cols) < w - 1:
            if cols == list(range(min(cols), max(cols) + 1)):
                choices.append((len(cols), r, max(cols)))

    out = [row[:] for row in grid]
    if choices:
        _, r, end = min(choices)
        for c in range(end + 1, w):
            out[r][c] = 1
    return out
